mapper.select:
SELECT TO_CHAR(d.leave_date, 'YYYY-MM-DD') AS "from",
       TO_CHAR(d.leave_date, 'YYYY-MM-DD') AS "to",
       CASE d.leave_type WHEN 'LV_FULL' THEN 'FULL'
                         WHEN 'LV_AM'   THEN 'AM'
                         ELSE 'PM' END AS kind
  FROM calendar_event e
  JOIN leave_request_day d ON d.company_id = e.company_id AND d.leave_request_day_id = e.leave_request_day_id
 WHERE e.company_id = #{companyId}
   AND e.owner_employee_id = #{employeeId}
   AND e.event_type = 'EV_LEAVE'
   AND e.starts_at >= #{from}
   AND e.starts_at < #{to}
 ORDER BY d.leave_date

SELECT COUNT(*)
  FROM calendar_event e
 WHERE e.company_id = #{companyId}
   AND e.starts_at >= #{from}
   AND e.starts_at < #{to}
   AND

SELECT d.department_name
  FROM employee me
  JOIN department d ON d.company_id = me.company_id AND d.department_id = me.department_id
 WHERE me.company_id = #{companyId}
   AND me.employee_id = #{employeeId}

mapper.delete:
DELETE FROM calendar_event
 WHERE company_id = #{companyId}
   AND calendar_event_id = #{eventId}
   AND (event_type IS NULL OR event_type != 'EV_LEAVE')
